WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pc_dc_round_table'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '圆桌问题', 'kp-pc-dc-round-table', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "圆桌排列"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "N个人围成一圈，排列数 = (N-1)！。这是因为圆桌没有首尾之分。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“5个人围着一张圆桌坐下，有几种坐法？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "因为圆桌可以旋转，甲乙丙、乙丙甲、丙甲乙 在圆桌上是同一种坐法。所以直线排列的全排列 N! 必须除以 N（N种旋转同构），即 N! / N = (N-1)!。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 5人围桌而坐，其中甲乙两人必须相邻。有几种坐法？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "先捆绑：把甲乙捆成一个大包，现在相当于只有 4 个人在圆桌上排座位。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "大圆排：4 个人的圆桌排列数 = (4-1)! = 3! = 6 种。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "小直排：甲乙两人在包裹内部是可以互换左右的（这是直线排，不受圆桌影响），A(2,2) = 2 种。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "总计：6 × 2 = 12 种。"}]}]}]}]}$$ AS jsonb), NULL, '圆桌问题的核心考点与实战推导。', category_node.id, CAST('["数量关系", "排列组合", "圆桌问题"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pc_dc_round_table", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
